import { useRef } from "react";
import { Platform } from "react-native";
import { Host } from "@expo/ui";
import { Slider as SwiftUISlider } from "@expo/ui/swift-ui";
import { disabled as swiftUIDisabled } from "@expo/ui/swift-ui/modifiers";
import { Slider as ComposeSlider } from "@expo/ui/jetpack-compose";
import { SeekBarLayout, useSeekBarModel } from "@/components/nyc-tron/ui/components/forge/NativeSeekBar.shared";
import type { NativeSeekBarProps } from "@/components/nyc-tron/ui/components/forge/NativeSeekBar.types";

export type { NativeSeekBarBaseProps, NativeSeekBarCommitProps, NativeSeekBarProps } from "@/components/nyc-tron/ui/components/forge/NativeSeekBar.types";

/**
 * Frame-accurate seek bar on the OS slider: SwiftUI `Slider` on iOS, Material 3
 * `Slider` on Android, both from `@expo/ui`. Dragging previews through
 * `onPreview`; the seek commits once through `onCommit` when the OS reports
 * the drag ended (`onEditingChanged(false)` on iOS, `onValueChangeFinished` on
 * Android). The step buttons commit once per press.
 *
 * On iOS a value change outside a drag, such as a VoiceOver increment,
 * commits on its own. Android's TalkBack and keyboard steps already end with
 * `onValueChangeFinished`.
 *
 * Requires @expo/ui native APIs on a verified Expo SDK 58 host. Not a WinUI,
 * Spark SDK 55, audio decoder or Forge engine adapter.
 */
export function NativeSeekBar(props: NativeSeekBarProps) {
  const { model, shown, step } = useSeekBarModel(props);
  // Whether SwiftUI reported a drag in progress. Kept out of render state:
  // it only routes the next value change.
  const editing = useRef(false);
  const slider = Platform.OS === "android"
    ? <ComposeSlider value={model.position} min={0} max={1} enabled={!model.off}
        onValueChange={model.move} onValueChangeFinished={() => model.release()} />
    : <SwiftUISlider value={model.position} min={0} max={1}
        modifiers={model.off ? [swiftUIDisabled(true)] : []}
        onEditingChanged={isEditing => {
          editing.current = isEditing;
          if (!isEditing) model.release();
        }}
        onValueChange={value => {
          model.move(value);
          if (!editing.current) model.release();
        }} />;
  // Only the slider is an @expo/ui host; the transport is app-token RN.
  return <SeekBarLayout props={props} shown={shown} step={step} off={model.off}
    slider={<Host key={model.key} style={{ width: "100%" }}>{slider}</Host>} />;
}

import { useLayoutEffect, useRef, type ReactNode } from "react";
import { Text, View } from "react-native";
import { createStore, type StoreApi } from "zustand/vanilla";
import { useStore } from "zustand";
import { Button } from "@/components/nyc-tron/ui/components/Button";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { clampFrame, formatTimecode, frameToPosition, positionToFrame } from "@/components/nyc-tron/ui/components/forge/timebase";
import type { NativeSeekBarProps } from "@/components/nyc-tron/ui/components/forge/NativeSeekBar.types";

import {controlIdentity} from "@/components/nyc-tron/ui/components/forge/inputs/useScopedControl";

type Drag = { preview: number | undefined };

/** What a platform slider needs from the shared seek-bar state. */
export interface SeekBarModel {
  /** True when disabled or the media has no frames. */
  readonly key:string;
  readonly off: boolean;
  /** Slider value in [0, 1]: the dragged frame mid-drag, otherwise `frame`. */
  readonly position: number;
  /** A drag tick at slider position `position`: previews, never commits. */
  readonly move: (position: number) => void;
  /**
   * The drag ended. Commits the frame at `position` when the platform reports
   * one, otherwise the last previewed frame. A second call commits nothing.
   */
  readonly release: (position?: number) => void;
}

const toFrame = (position: number, durationFrames: number) =>
  positionToFrame(Math.min(1, Math.max(0, position)), durationFrames);

/**
 * Preview/commit state shared by the iOS, Android and web seek bars, modelled
 * on `LevelFader`: drag ticks go to `onPreview`, the release goes to
 * `onCommit` once. `onSeek` is the deprecated name for `onCommit`; when both
 * are passed only `onCommit` runs, so no gesture fires twice.
 */
export function useSeekBarModel(props: NativeSeekBarProps) {
  const { frame, durationFrames, stepFrames = 1, disabled = false, onPreview } = props;
  if (!Number.isSafeInteger(durationFrames) || durationFrames < 0 ||
      !Number.isSafeInteger(stepFrames) || stepFrames < 1)
    throw new RangeError("Invalid frame count or step");
  const onCommit = props.onCommit ?? props.onSeek;
  if (typeof onCommit !== "function") throw new TypeError("NativeSeekBar needs onCommit (or the deprecated onSeek)");
  const boundary=JSON.stringify([...controlIdentity(props.scope??"native-seek",props.revision??0),durationFrames,stepFrames,disabled]);
  const current = clampFrame(frame, durationFrames);
  const off = disabled || durationFrames === 0;
  const latest = useRef({ boundary,current, durationFrames, off, onPreview, onCommit });
  useLayoutEffect(()=>{latest.current = { boundary,current, durationFrames, off, onPreview, onCommit };});
  const local = useRef<StoreApi<Drag> | null>(null);
  if (!local.current) local.current = createStore<Drag>(() => ({ preview: undefined }));
  const store = local.current;
  useLayoutEffect(()=>{store.setState({preview:undefined});},[boundary,store]);
  const preview = useStore(store, s => s.preview);
  const shown = preview ?? current;

  const commit = (next: number) => {
    const p = latest.current;
    if(p.boundary!==boundary)return;
    store.setState({ preview: undefined });
    if (p.off || next === p.current) return;
    p.onCommit(next);
  };
  const model: SeekBarModel = {
    key:boundary,off,
    position: frameToPosition(shown, durationFrames),
    move: position => {
      const p = latest.current;
      if (p.boundary!==boundary||p.off || !Number.isFinite(position)) return;
      const next = toFrame(position, p.durationFrames);
      if (next === (store.getState().preview ?? p.current)) return;
      store.setState({ preview: next });
      p.onPreview?.(next);
    },
    release: position => {
      const p = latest.current;
      if(p.boundary!==boundary)return;
      const dragged = store.getState().preview;
      if (position !== undefined && Number.isFinite(position)) commit(toFrame(position, p.durationFrames));
      else if (dragged !== undefined) commit(dragged);
    },
  };
  /** Step buttons: one commit per press, no preview. */
  const step = (delta: number) => commit(clampFrame(latest.current.current + delta, latest.current.durationFrames));
  return { model, shown, step };
}

/**
 * The seek bar frame around a platform slider: the slider on top, then one
 * row with step back, timecode and step forward (Forge PR #25, #27). The
 * transport is app-token RN, so it follows the app theme rather than the OS
 * scheme that `@expo/ui` text follows.
 */
export function SeekBarLayout({ props, shown, step, off, slider }: {
  props: NativeSeekBarProps;
  shown: number;
  step: (delta: number) => void;
  off: boolean;
  slider: ReactNode;
}) {
  const {
    scope:_scope,revision:_revision,frame: _frame, durationFrames, frameRate, onPreview: _preview, onCommit: _commit, onSeek: _seek,
    stepFrames = 1, dropFrameTimecode = false, disabled: _disabled, className, unstyled = false, style, ...rest
  } = props;
  const tc = (f: number) => formatTimecode(f, frameRate, { dropFrame: dropFrameTimecode });
  return <View {...rest}
    {...{ className: joinClasses("w-full", !unstyled && "rounded-control bg-surface-raised p-3", className) }}
    style={style}>
    {slider}
    <View style={{ flexDirection: "row", alignItems: "center", gap: 8, marginTop: 8 }}>
      <Button title={`−${stepFrames} frame`} variant="secondary" size="sm" disabled={off}
        onPress={() => step(-stepFrames)} />
      <Text selectable {...{ className: joinClasses(!unstyled && "text-text") }}
        style={{ flex: 1, minWidth: 0, textAlign: "center", fontVariant: ["tabular-nums"] }}>
        {`${tc(shown)} / ${tc(durationFrames)}`}
      </Text>
      <Button title={`+${stepFrames} frame`} variant="secondary" size="sm" disabled={off}
        onPress={() => step(stepFrames)} />
    </View>
  </View>;
}

import type { ViewProps } from "react-native";
import type { FrameRate } from "@/components/nyc-tron/ui/components/forge/timebase";

/** Props shared by every {@linkcode NativeSeekBarProps} variant. */
export interface NativeSeekBarBaseProps extends Omit<ViewProps,"children"> {
  /** Stable media/document identity; change revision when replacing the source. */
  readonly scope?:string;readonly revision?:string|number;
  /** The player's reported frame. The thumb and timecode show it except mid-drag. */
  readonly frame:number;
  readonly durationFrames:number;
  readonly frameRate:FrameRate;
  /**
   * Called with each new frame while the thumb is dragged, for a fast or
   * approximate seek. A repeated frame is not reported twice. Step buttons
   * and screen-reader steps do not call it; they commit directly.
   */
  readonly onPreview?:(frame:number)=>void;
  /**
   * Frames moved by one press of a step button.
   * @default 1
   */
  readonly stepFrames?:number;
  /** @default false */
  readonly dropFrameTimecode?:boolean;
  /** @default false */
  readonly disabled?:boolean;
  className?:string;
  /** Drops the library recipe from the wrapper and timecode; the native Expo Slider keeps OS behavior. */
  unstyled?:boolean;
}

/** Commit callbacks for `NativeSeekBar`: `onCommit`, or the deprecated `onSeek`. */
export type NativeSeekBarCommitProps =
  | {
    /**
     * Called once per completed drag when the finger or pointer is released,
     * once per step button press, and once per screen-reader or keyboard step.
     * Not called when the frame is unchanged.
     *
     * When both `onCommit` and `onSeek` are passed, only `onCommit` is called.
     */
    readonly onCommit:(frame:number)=>void;
    /** @deprecated Use `onCommit`. Ignored when `onCommit` is passed. */
    readonly onSeek?:(frame:number)=>void;
  }
  | {
    readonly onCommit?:undefined;
    /**
     * @deprecated Use `onCommit`. Kept as an alias with the same timing: once
     * per release or step, never on drag ticks. Before this change it fired on
     * every slider tick.
     */
    readonly onSeek:(frame:number)=>void;
  };

/** Props for `NativeSeekBar`. Pass `onCommit` (or the deprecated `onSeek`). */
export type NativeSeekBarProps=NativeSeekBarBaseProps&NativeSeekBarCommitProps;

import { useEffect, useRef, type ComponentRef } from "react";
import { View } from "react-native";
import { Host, Slider } from "@expo/ui";
import { SeekBarLayout, useSeekBarModel } from "@/components/nyc-tron/ui/components/forge/NativeSeekBar.shared";
import type { NativeSeekBarProps } from "@/components/nyc-tron/ui/components/forge/NativeSeekBar.types";

export type { NativeSeekBarBaseProps, NativeSeekBarCommitProps, NativeSeekBarProps } from "@/components/nyc-tron/ui/components/forge/NativeSeekBar.types";

/** The part of a DOM node this file uses; React Native Web Views are DOM nodes. */
type ChangeTarget = {
  addEventListener(type: "change", listener: (event: { target: unknown }) => void): void;
  removeEventListener(type: "change", listener: (event: { target: unknown }) => void): void;
};

/**
 * Web build of `NativeSeekBar` over the `@expo/ui` universal slider, an
 * `<input type="range">`. Its `input` events preview through `onPreview`.
 * The browser fires one DOM `change` when the pointer is released and one per
 * arrow-key step; that event commits through `onCommit`. `@expo/ui` does not
 * expose `change`, so the wrapper View listens for it as it bubbles.
 */
export function NativeSeekBar(props: NativeSeekBarProps) {
  const { model, shown, step } = useSeekBarModel(props);
  const host = useRef<ComponentRef<typeof View> | null>(null);
  useEffect(() => {
    // React Native Web renders a View as a DOM element.
    const node = host.current as unknown as ChangeTarget | null;
    if (!node) return;
    const onChange = (event: { target: unknown }) => {
      const value = (event.target as { value?: unknown } | null)?.value;
      if (typeof value === "string") model.release(Number.parseFloat(value));
    };
    node.addEventListener("change", onChange);
    return () => node.removeEventListener("change", onChange);
  }, [model.key]);
  return <SeekBarLayout props={props} shown={shown} step={step} off={model.off}
    slider={<View key={model.key} ref={host} style={{ width: "100%" }}>
      <Host style={{ width: "100%" }}>
        <Slider min={0} max={1} value={model.position} disabled={model.off} onValueChange={model.move} />
      </Host>
    </View>} />;
}

import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
